    pq = [(h_start, 0, start)]
    costs = {start: 0}
    parents = {}

    while pq:
        f, g, current = heapq.heappop(pq)

        if current == goal:
            path = []
            while current in parents:
                path.append(current)
                current = parents[current]
            path.append(start)
            return path[::-1]

